<?php

namespace Tests\Unit;

use App\Constants\DiscountConstants;
use PHPUnit\Framework\TestCase;

class DiscountConstantsTest extends TestCase
{
    public function test_action_type_options_returns_associative_array_keyed_by_action_type_values(): void
    {
        $options = DiscountConstants::actionTypeOptions();

        $this->assertIsArray($options);
        $this->assertArrayHasKey(DiscountConstants::ACTION_TYPE_ANY, $options);
        $this->assertArrayHasKey(DiscountConstants::ACTION_TYPE_RENEWAL, $options);
        $this->assertArrayHasKey(DiscountConstants::ACTION_TYPE_UPGRADE, $options);
    }

    public function test_action_type_options_covers_all_action_types(): void
    {
        $options = DiscountConstants::actionTypeOptions();

        $this->assertSame(
            DiscountConstants::ACTION_TYPES,
            array_keys($options),
            'actionTypeOptions() keys must match ACTION_TYPES exactly'
        );
    }

    public function test_action_type_options_values_are_non_empty_strings(): void
    {
        foreach (DiscountConstants::actionTypeOptions() as $key => $label) {
            $this->assertIsString($label, "Label for '{$key}' must be a string");
            $this->assertNotEmpty($label, "Label for '{$key}' must not be empty");
        }
    }
}
